		PermisoPorRol on PermisoPorRol.Id = RolPermisoPorRol.PermisoPorRol_Id inner join 
		Rol on Rol.Id = RolPermisoPorRol.Rol_Id
	WHERE Rol.Nombre = 'API ORDENES DE CARGA' and PermisoPorRol.Permiso = 'API ORDENES DE CARGA')
BEGIN
	INSERT INTO RolPermisoPorRol VALUES (
		(SELECT id FROM rol WHERE rol.Nombre = 'API ORDENES DE CARGA'),
		(SELECT id FROM PermisoPorRol WHERE PermisoPorRol.Permiso = 'API ORDENES DE CARGA'))
END


-- Asignar permiso 'EDITAR SUPLENTE' a los roles correspondientes
INSERT INTO RolPermisoPorRol (Rol_Id, PermisoPorRol_Id)
SELECT R.Id, P.Id
FROM
	Rol R left join
	PermisoPorRol P on 1=1 left join
	RolPermisoPorRol RP on RP.Rol_Id = R.Id and RP.PermisoPorRol_Id = P.Id
WHERE
	RP.Rol_Id is null and RP.PermisoPorRol_Id is null and
	P.Permiso = 'EDITAR SUPLENTE' and
	R.Nombre in (
		'VER TODOS LOS ESTADOS DE ES',
		'ADMINISTRACION')

IF NOT EXISTS(SELECT 1 FROM RolPermisoPorRol inner join PermisoPorRol on PermisoPorRol.Id = RolPermisoPorRol.PermisoPorRol_Id inner join Rol on Rol.Id = RolPermisoPorRol.Rol_Id WHERE Rol.Nombre = 'NO GRANOS' and PermisoPorRol.Permiso = 'CARGAR FACT PROV') BEGIN insert into RolPermisoPorRol values ((select id from rol where rol.Nombre = 'NO GRANOS'),(select id from PermisoPorRol where PermisoPorRol.Permiso = 'CARGAR FACT PROV')) END
IF NOT EXISTS(SELECT 1 FROM RolPermisoPorRol inner join PermisoPorRol on PermisoPorRol.Id = RolPermisoPorRol.PermisoPorRol_Id inner join Rol on Rol.Id = RolPermisoPorRol.Rol_Id WHERE Rol.Nombre = 'REPORTE FACTURAS CERTIFICACIONES' and PermisoPorRol.Permiso = 'CARGAR FACT PROV') BEGIN insert into RolPermisoPorRol values ((select id from rol where rol.Nombre = 'REPORTE FACTURAS CERTIFICACIONES'),(select id from PermisoPorRol where PermisoPorRol.Permiso = 'CARGAR FACT PROV')) END
IF NOT EXISTS(SELECT 1 FROM RolPermisoPorRol inner join PermisoPorRol on PermisoPorRol.Id = RolPermisoPorRol.PermisoPorRol_Id inner join Rol on Rol.Id = RolPermisoPorRol.Rol_Id WHERE Rol.Nombre = 'COMPRAS RRHH' and PermisoPorRol.Permiso = 'COMPRAS RRHH') BEGIN insert into RolPermisoPorRol values ((select id from rol where rol.Nombre = 'COMPRAS RRHH'),(select id from PermisoPorRol where PermisoPorRol.Permiso = 'COMPRAS RRHH')) END


